  ('consider_selling_follow_up', 'lc-v3am-csf-hi-1', 'consider_selling_follow_up — Indian (Hindi or Other) (seller conversation v3, acquisition os)', 'Indian (Hindi or Other)', 'बस पूछ रहा हूँ: अगर आँकड़े सही बैठें, तो क्या आप एक ऑफ़र देखना चाहेंगे?', 'Just checking in: if the numbers made sense, would you look at a proposal?', 'S2', 'Stage 2 Consider Selling Follow-Up', true, 'missing_language'),
  ('price_high_condition_probe', 'lc-v3am-phc-pt-1', 'price_high_condition_probe — Portuguese (seller conversation v3, acquisition os)', 'Portuguese', 'Entendi. O imóvel está reformado ou precisa de obras?', 'Got it. Is the property updated, or does it need work?', 'S4', 'Stage 4 Condition (near value)', true, 'missing_language'),
